  }
  const act=aS/8,inh=iS/8,act2=aS2/8,inh2=iS2/8;
  const bg1=(Math.sin(dx*0.04+dy*0.025+t*0.8)+Math.sin(dx*0.03-dy*0.04+t*1.1))/2;
  const bg2=(Math.sin(dx*0.08+dy*0.05+t*1.6)+Math.sin(dx*0.06-dy*0.08+t*2.2))/4;
  const bg3=(Math.sin(dx*0.16+dy*0.1+t*3.2)+Math.sin(dx*0.12-dy*0.16+t*4.4))/8;
