  const r2=Math.tanh((act2-inh2*0.6+bg*0.2-spiral*0.5)*1.8);
  const reaction=(r1+r2*0.4)/1.4;
  const c1=Math.tanh((Math.sin(dx*0.15)*Math.sin(dy*0.15)+Math.sin((dx+dy)*0.1+t)*0.5)*1.5)*0.3;
  const c2=Math.tanh((Math.sin(dx*0.22+t*0.3)*Math.sin(dy*0.22-t*0.2)+Math.sin((dx-dy)*0.15+t*0.7)*0.3)*1.2)*0.15;
  const micro=Math.sin(dx*0.3+t*0.5)*Math.sin(dy*0.3-t*0.4)*Math.sin((dx+dy)*0.2+t*0.3)*0.1;
