  const pal=[[6,12,52],[12,45,88],[18,85,120],[25,140,130],[60,175,120],[160,190,70],[210,175,50],[215,120,55],[195,75,65],[160,45,70],[100,25,65],[50,15,55],[20,12,50],[6,12,52]];
